H('35.c.7.F',3,"Which sentence uses academic vocabulary?","The author's argument is supported by evidence.",["The author did stuff.","It was cool, I guess.","The book was good lol."],"Academic language is precise and formal.")
H('35.c.7.F',3,"Using words learned in a history unit while answering a question shows:","use of content vocabulary",["a spelling mistake","a lack of effort","a rhyme"],"Content words show learning.")
H('35.c.7.G',3,"'The empty chair sat by the window.' A reader may discuss the chair's implicit meaning as:","a sign of someone's absence",["an advertisement","a table of data","a legal notice"],"Implicit meaning is suggested.")
H('35.c.7.G',3,"Explicit meaning is the meaning that is:","stated directly",["hidden","assumed","unspoken"],"Explicit means plainly stated.")
H('35.c.7.H',3,"Which register is best for a letter to a principal?","formal and respectful",["slangy and rushed","jokey and sarcastic","texting shorthand"],"Register should fit the audience.")
H('35.c.7.H',3,"When speaking to a friend, a learner may use:","a casual register",["a legal register","a technical register","a ceremonial register"],"Casual language suits friends.")
H('35.c.7.I',3,"After hearing a classmate's strong evidence, a reader changes her interpretation. This shows:","willingness to reflect and adjust",["poor reading","lack of effort","copying"],"Good readers revise ideas.")
H('35.c.7.I',3,"Valid evidence is evidence that is:","accurate and relevant",["loud","long","popular only"],"Valid evidence is sound and related to the claim.")
H('35.c.7.J',4,"A student argues, 'The author is wrong because paragraph 3 ignores the data.' This is:","challenging a claim with text evidence",["agreeing without proof","summarizing only","insulting the writer"],"The student cites the text.")
H('35.c.7.J',4,"Defending a claim requires:","reasons and evidence from the text",["volume","repetition only","opinions alone"],"Defenses rely on support.")
H('35.c.7.K',2,"A newcomer says, 'I happy today.' This shows the learner is:","expressing feelings with simple language",["refusing to speak","writing an essay","citing sources"],"Early expression uses simple forms.")
H('35.c.7.K',2,"As proficiency grows, a learner's expression of ideas moves toward:","more detailed and varied sentences",["shorter silences only","fewer ideas","only single words"],"Language expands with proficiency.")

H('35.c.8.A',4,"A character who keeps helping others despite losing everything most clearly develops the theme of:","generosity",["boredom","greed","luck"],"The character's choices show the theme.")
H('35.c.8.A',4,"Comparing similar themes in two stories means:","showing how each plot develops the same idea",["listing authors","counting pages","retelling one only"],"Theme comparison looks at development.")
H('35.c.8.B',4,"An archetype is:","a recurring character type, such as the hero or mentor",["a rare spelling","a type of rhyme","a map symbol"],"Archetypes recur across literature.")
H('35.c.8.B',4,"A character who is kind but also stubborn feels:","complex and believable",["flat and unreal","absent","unfinished"],"Mixed traits make characters real.")
H('35.c.8.C',4,"An isolated scene in which a character makes a key choice contributes to the plot by:","changing what happens next",["ending the book","removing the conflict","listing the setting"],"Scenes drive the plot.")
H('35.c.8.C',4,"The climax of a plot is:","the turning point of highest tension",["the title","the first sentence","the index"],"The climax is the peak of conflict.")
H('35.c.8.D',4,"A story set during a drought makes characters' choices about water seem:","urgent and meaningful",["unimportant","silly","unrelated"],"Setting raises the stakes.")
H('35.c.8.D',4,"Cultural setting can affect a plot because customs shape:","what characters value and do",["the font","the page count","the cover"],"Culture influences characterization and plot.")

H('35.c.9.A',3,"Why read literature from different periods and countries?","to see how ideas and cultures vary",["to avoid reading","to finish quickly","to ignore history"],"World literature widens perspective.")
H('35.c.9.A',3,"A classic novel written long ago and still read today is an example of:","world literature across periods",["a menu","a bus pass","a brochure"],"Literature spans time.")
H('35.c.9.B',4,"In poetry, 'rain' and 'train' at line endings form an:","end rhyme",["internal rhyme","slant rhyme","free verse"],"End rhymes occur at line ends.")
H('35.c.9.B',4,"A rhyme inside a single line is an:","internal rhyme",["end rhyme","title rhyme","stanza break"],"Internal rhyme occurs within a line.")
H('35.c.9.C',4,"In a play, the audience knows a secret the characters do not. This is:","dramatic irony",["an aside","a soliloquy","a stage direction"],"Dramatic irony depends on audience knowledge.")
H('35.c.9.C',4,"Stage directions in a script tell actors and directors:","how to move and speak",["the index","the bibliography","the price"],"Stage directions guide performance.")
H('35.c.9.D.i',3,"An essay conclusion should:","restate the thesis and give a final thought",["introduce a new topic","list sources","stop mid-idea"],"Conclusions close the argument.")
H('35.c.9.D.i',3,"Pertinent examples in an essay are:","examples that clearly relate to the thesis",["any interesting story","jokes only","facts from another topic"],"Pertinent means relevant.")
H('35.c.9.D.ii',3,"A caption under a photograph in an article explains:","what the picture shows",["who printed the page","the author's age","the table of contents"],"Captions describe images.")
H('35.c.9.D.ii',3,"A bibliography at the end of a book lists:","the sources used",["the characters","the page count","the vocabulary"],"A bibliography credits sources.")
H('35.c.9.D.iii',3,"An article that explains how a problem happened and what it caused uses:","cause and effect",["sequence of steps","description only","alphabetical order"],"It links causes to results.")
H('35.c.9.D.iii',3,"A text ordered by time (first, next, last) uses:","temporal sequence",["compare and contrast","problem and solution","description"],"Time order shows sequence.")
H('35.c.9.D.iv',4,"If an essay compares two cultures, which design fits its thesis?","organizing by similarities and then differences",["random paragraphs","one long list","alphabetical sentences"],"Organization should support the thesis.")
H('35.c.9.D.iv',4,"The relationship between organizational design and thesis means:","the structure should support the main point",["structure is unimportant","the thesis is hidden","only the title matters"],"Design serves the thesis.")
H('35.c.9.E.i',3,"A convincing conclusion in an argument:","restates the claim and leaves the reader with a final appeal",["adds an unrelated topic","apologizes","repeats the introduction exactly"],"Strong conclusions reinforce the claim.")
H('35.c.9.E.i',3,"Appeals to emotion are called:","pathos",["logos","ethos","syntax"],"Pathos appeals to feelings.")
H('35.c.9.E.ii',4,"Statistics, expert quotes and examples are:","various types of evidence",["a lack of research","only opinion","a single guess"],"Arguments use several kinds of evidence.")
H('35.c.9.E.ii',4,"A concession like 'Some will argue homework builds discipline' is typically followed by:","a rebuttal",["a title","an index","a rhyme"],"The writer then answers the opposing point.")
H('35.c.9.E.iii',3,"An argument for city council to build a skate park is written for:","council members and community members",["no readers","toddlers only","a pet"],"The audience is identifiable.")
H('35.c.9.E.iii',3,"Knowing the reader helps a writer choose:","evidence and tone that persuade that audience",["a random font","the paper brand","the page number"],"Audience guides choices.")
H('35.c.9.E.iv',3,"An online article with an embedded video, links and an interactive chart is:","multimodal and digital",["a printed novel only","a paper map only","a handwritten note only"],"It combines modes online.")
H('35.c.9.E.iv',3,"Which feature is unique to digital texts?","hyperlinks",["page numbers","margins","covers"],"Hyperlinks connect online content.")

