H('35.c.11.D.ii',3,"Which sentence stays in the present tense throughout?","She reads the book and takes notes.",["She reads the book and took notes.","She read the book and takes notes.","She reads the book and will took notes."],"Both verbs are present tense.")
H('35.c.11.D.iii',3,"Choose the verb that agrees: 'Neither of the answers ___ correct.'","is",["are","were","be"],"Neither is singular.")
H('35.c.11.D.iii',3,"Choose the correct verb: 'The group of tourists ___ lost.'","seems",["seem","have seemed","were seeming"],"Group is a singular collective noun here.")
